package main

import (
	"bytes"
	"context"
	"encoding/json"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/store"
	"github.com/mellifera/mellifera/internal/stream"
)

// TestDescriptorFileMissing covers the composition-root stat gate
// (tombstone-lifecycle D6): a direct answer whose resolved original
// (parsed.absolute_path, the channel originalResolver reads) no longer
// exists on disk answers state missing / state_reason file_missing with NO
// play URL, the decision line naming both through the existing fields; a
// present file keeps today's answer exactly (direct floor, token-carrying
// /original URL); and an hls answer never stats the source — a stale source
// under a complete namespace still serves the published build.
func TestDescriptorFileMissing(t *testing.T) {
	ctx := context.Background()
	st := openJanitorStore(t)
	mediaSvc := &stream.Service{Root: t.TempDir(), Secret: []byte("descriptor-missing-test-secret")}

	seedItem := func(t *testing.T, id string, doc map[string]any) {
		t.Helper()
		raw, err := json.Marshal(doc)
		if err != nil {
			t.Fatalf("marshal doc for %s: %v", id, err)
		}
		if err := st.PutItem(ctx, store.Item{
			ID: id, ModuleID: "serial", LibraryID: 1, FileID: id, RelativePath: id + ".mp4",
			MediaType: "movie", Document: raw, SchemaVersion: 1,
		}); err != nil {
			t.Fatalf("PutItem %s: %v", id, err)
		}
	}

	dir := t.TempDir()
	present := filepath.Join(dir, "there.mp4")
	if err := os.WriteFile(present, []byte("fake mp4 bytes"), 0o644); err != nil {
		t.Fatalf("write present file: %v", err)
	}
	gone := filepath.Join(dir, "gone.mp4") // never created

	// Native-container floors (the codec chain never matters ahead of the
	// stat — a missing answer replaces it): one whose file vanished, one
	// whose file is present, and one vanished file under a live cooldown.
	ffNative := func() map[string]any {
		return map[string]any{
			"format":  map[string]any{"format_name": "mp4"},
			"streams": []any{map[string]any{"codec_type": "video", "codec_name": "h264"}},
		}
	}
	seedItem(t, "gone-item", map[string]any{
		"parsed":  map[string]any{"absolute_path": gone},
		"ffprobe": ffNative(),
	})
	seedItem(t, "present-item", map[string]any{
		"parsed":  map[string]any{"absolute_path": present},
		"ffprobe": ffNative(),
	})
	seedItem(t, "gone-cool-item", map[string]any{
		"parsed":  map[string]any{"absolute_path": gone},
		"streams": map[string]any{"state": stream.StateFailed},
		"ffprobe": ffNative(),
	})
	coolUntil := time.Now().Add(time.Hour)
	if err := st.RecordFailure(ctx, "gone-cool-item", streamsFailureLane, "failed", "ffmpeg exit 1", 1, coolUntil); err != nil {
		t.Fatalf("RecordFailure: %v", err)
	}
	// An hls answer over a vanished source: the published build is the
	// playable truth, so the descriptor must stay hls — a stat here would
	// retire a playable pack (D6's direct-only law).
	seedItem(t, "stale-source-hls", map[string]any{
		"parsed":  map[string]any{"absolute_path": gone},
		"streams": map[string]any{"state": stream.StateComplete, "playlist": "/media/stale-source-hls/n1/index.m3u8"},
	})

	// Capture the decision log for the whole pass (the decision_log_test
	// precedent; never parallel).
	var buf bytes.Buffer
	prev := slog.Default()
	slog.SetDefault(slog.New(slog.NewTextHandler(&buf, nil)))
	t.Cleanup(func() { slog.SetDefault(prev) })

	t.Run("missing_file_answers_missing_without_play_url", func(t *testing.T) {
		buf.Reset()
		pb, err := playbackDescriptor(ctx, st, mediaSvc, func(string) error { return nil }, false, "gone-item")
		if err != nil {
			t.Fatalf("playbackDescriptor(gone-item): %v", err)
		}
		if pb.Mode != stream.ModeDirect || pb.State != stream.StateMissing {
			t.Fatalf("descriptor = %s/%s, want %s/%s", pb.Mode, pb.State, stream.ModeDirect, stream.StateMissing)
		}
		if pb.StateReason != stream.ReasonFileMissing {
			t.Fatalf("state_reason = %q, want %q", pb.StateReason, stream.ReasonFileMissing)
		}
		if pb.PlayURL != "" {
			t.Fatalf("play URL = %q, want empty — never a URL that 404s behind a mounted player", pb.PlayURL)
		}
		// The decision log renders the answer through the existing fields —
		// and the missing truth beats the direct chain's codec judgment.
		ln := decisionLine(t, &buf, "gone-item")
		for _, field := range []string{"state=" + stream.StateMissing, "reason=" + stream.ReasonFileMissing} {
			if !strings.Contains(ln, field) {
				t.Fatalf("decision line %q lacks %q", ln, field)
			}
		}
	})

	t.Run("missing_file_beats_live_cooldown_in_the_log", func(t *testing.T) {
		buf.Reset()
		pb, err := playbackDescriptor(ctx, st, mediaSvc, func(string) error { return nil }, false, "gone-cool-item")
		if err != nil {
			t.Fatalf("playbackDescriptor(gone-cool-item): %v", err)
		}
		if pb.Mode != stream.ModeDirect || pb.State != stream.StateMissing || pb.StateReason != stream.ReasonFileMissing || pb.PlayURL != "" {
			t.Fatalf("descriptor = %s/%s/%q/%q, want direct/missing/file_missing/empty",
				pb.Mode, pb.State, pb.StateReason, pb.PlayURL)
		}
		// A pack-failed row still gating the item must not rename the truth:
		// nothing failed that a retry could fix, so the log names file_missing
		// even under a live cooldown.
		ln := decisionLine(t, &buf, "gone-cool-item")
		if !strings.Contains(ln, "reason="+stream.ReasonFileMissing) {
			t.Fatalf("decision line %q lacks reason=%q — cooldown must not rename a missing file", ln, stream.ReasonFileMissing)
		}
	})

	t.Run("present_file_keeps_todays_answer", func(t *testing.T) {
		buf.Reset()
		pb, err := playbackDescriptor(ctx, st, mediaSvc, func(string) error { return nil }, false, "present-item")
		if err != nil {
			t.Fatalf("playbackDescriptor(present-item): %v", err)
		}
		// Today's native-floor answer, byte for byte in shape: direct floor,
		// state none, no state_reason, the token-carrying /original URL.
		if pb.Mode != stream.ModeDirect || pb.State != stream.StateNone || pb.StateReason != "" {
			t.Fatalf("descriptor = %s/%s/%q, want direct/none/empty", pb.Mode, pb.State, pb.StateReason)
		}
		if !strings.HasPrefix(pb.PlayURL, "/media/present-item/original?token=") || strings.HasSuffix(pb.PlayURL, "token=") {
			t.Fatalf("play URL = %q, want /media/present-item/original?token=<fresh>", pb.PlayURL)
		}
		if ln := decisionLine(t, &buf, "present-item"); !strings.Contains(ln, "state="+stream.StateNone) || !strings.Contains(ln, "reason="+reasonUnpackaged) {
			t.Fatalf("decision line %q drifted from today's native-floor record", ln)
		}
	})

	t.Run("hls_answer_never_stats_the_source", func(t *testing.T) {
		buf.Reset()
		pb, err := playbackDescriptor(ctx, st, mediaSvc, func(string) error { return nil }, false, "stale-source-hls")
		if err != nil {
			t.Fatalf("playbackDescriptor(stale-source-hls): %v", err)
		}
		// The source is gone (same vanished path gone-item answers missing
		// for) yet the answer stays hls — proof the gate never statted a
		// published build's stale source.
		if pb.Mode != stream.ModeHls || pb.State != stream.StateComplete || pb.StateReason != "" || pb.PlayURL == "" {
			t.Fatalf("descriptor = %s/%s/%q/%q, want hls/complete/empty/playable", pb.Mode, pb.State, pb.StateReason, pb.PlayURL)
		}
		if !strings.HasPrefix(pb.PlayURL, "/media/stale-source-hls/n1/index.m3u8?token=") {
			t.Fatalf("play URL = %q, want the published playlist", pb.PlayURL)
		}
	})
}

// decisionLine fetches the ONE decision line the pass captured for item.
func decisionLine(t *testing.T, buf *bytes.Buffer, item string) string {
	t.Helper()
	var lines []string
	for _, ln := range strings.Split(strings.TrimSpace(buf.String()), "\n") {
		if strings.Contains(ln, `msg="playback: descriptor"`) && strings.Contains(ln, "item="+item) {
			lines = append(lines, ln)
		}
	}
	if len(lines) != 1 {
		t.Fatalf("captured %d decision lines for %s, want 1; output:\n%s", len(lines), item, buf.String())
	}
	return lines[0]
}
